noncomputable def LerayProjection (f : FourierCoeff) : FourierCoeff := fun k j =>
  if k = 0 then f k j
  else f k j - (∑ i : Fin 3, (k i : ℂ) * f k i) * (k j : ℂ) / (∑ i : Fin 3, (k i : ℂ)^2)

theorem Submodule.starProjection_le_starProjection_iff {U V : Submodule 𝕜 E}
    [U.HasOrthogonalProjection] [V.HasOrthogonalProjection] :
    U.starProjection ≤ V.starProjection ↔ U ≤ V
